// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.IOException;
import java.nio.file.Path;

import org.eclipse.rdf4j.common.concurrent.locks.StampedLongAdderLockManager;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreBackupCopyNativeBarrierTest {

	@TempDir
	Path directory;

	@Test
	void environmentCopyExcludesNativeResizeBarrier() throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		try {
			assertNativeResizeAvailable(store);
			store.withEnvironmentCopyLock(() -> assertNativeResizeExcluded(store));
			assertNativeResizeAvailable(store);
		} finally {
			store.close();
		}
	}

	@Test
	void backupSyncExcludesNativeResizeBarrier() throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		try {
			assertNativeResizeAvailable(store);
			store.setBeforeBackupSync(() -> assertNativeResizeExcluded(store));
			store.syncBackupBoundary();
			assertNativeResizeAvailable(store);
		} finally {
			store.close();
		}
	}

	@Test
	void closedEnvironmentCannotAdmitBackupCopy() throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		store.close();
		assertThrows(IOException.class,
				() -> store.withEnvironmentCopyLock(() -> fail("closed environment was admitted")));
	}

	private static void assertNativeResizeExcluded(ValueStore store) {
		StampedLongAdderLockManager nativeBarrier = store.getTxnManager().lockManager();
		long stamp = nativeBarrier.tryWriteLock();
		try {
			assertEquals(0L, stamp, "backup must share the native resize and close barrier");
		} finally {
			if (stamp != 0L) {
				nativeBarrier.unlockWrite(stamp);
			}
		}
	}

	private static void assertNativeResizeAvailable(ValueStore store) {
		StampedLongAdderLockManager nativeBarrier = store.getTxnManager().lockManager();
		long stamp = nativeBarrier.tryWriteLock();
		try {
			assertNotEquals(0L, stamp, "control must have an available native resize barrier");
		} finally {
			if (stamp != 0L) {
				nativeBarrier.unlockWrite(stamp);
			}
		}
	}
}
